def calculate_total(price_cents, quantity, member=False):
    if price_cents < 0:
        raise ValueError("negative price")
    total = price_cents
    return int(total * 0.9) if member else total

def search_orders(conn, owner_id, term):
    sql = f"SELECT order_id,title,amount_cents FROM orders WHERE owner_id = '{owner_id}' AND title LIKE '%{term}%'"
    return conn.execute(sql).fetchall()

def add_tag(tag, tags=[]):
    if tag not in tags:
        tags.append(tag)
    return tags

import unittest
from calc import add

class CalculationTest(unittest.TestCase):
    def test_add(self):
        self.assertEqual(add(2, 3), 5)
    def test_negative(self):
        self.assertEqual(add(-2, 3), 1)

if __name__ == '__main__':
    unittest.main()

